/**
 * CMS reads — the single gateway to Velite content.
 *
 * `.velite` is generated by `pnpm content`, which runs before dev, build,
 * typecheck, and tests (see package.json pre-scripts). Every template reads
 * through this module — never through src/data directly.
 */

// .velite is gitignored and generated; its index.d.ts provides the types.
import {
  industries as cmsIndustries,
  insights as cmsInsights,
  services as cmsServices,
} from '../../.velite'
import type { Industry, Insight, Service } from '../../.velite'

export type { Industry, Insight, Service }

function byOrder(a: { order: number }, b: { order: number }) {
  return a.order - b.order
}

/** Services in the required order: Web → RPO → VA → Accounting → Legal. */
export const cmsServicesByOrder: Service[] = [...cmsServices].sort(byOrder)

export function cmsGetService(slug: string): Service | undefined {
  return cmsServices.find((s) => s.slug === slug)
}

export const cmsIndustriesAll: Industry[] = cmsIndustries

export function cmsGetIndustry(slug: string): Industry | undefined {
  return cmsIndustries.find((i) => i.slug === slug)
}

/** Insights, newest first; featured first for the home page. */
export const cmsInsightsByDate: Insight[] = [...cmsInsights].sort((a, b) =>
  b.date.localeCompare(a.date),
)

export function cmsGetInsight(slug: string): Insight | undefined {
  return cmsInsights.find((i) => i.slug === slug)
}
